styles:
.b-showcase-column {
    padding-block: var(--site-space-6);
}

.b-showcase-column__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-column__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-column__frame {
    max-width: 20rem;
    padding: var(--site-space-3);
    border: 1px dashed var(--site-color-border);
}
